Function mensaje <- QueMostrar(codigo As Integer, cambio As Integer)
  Define mensaje As String;
  If codigo = 200 Then
    mensaje <- "Precio: " + toText(2 * cambio);
  Else
    mensaje <- "Servicio no disponible (" + toText(codigo) + ")";
  EndIf
EndFunction

Algorithm QueHacer
  Define codigo As Integer;
  Define cambio As Integer;
  Read codigo;
  Read cambio;
  Write QueMostrar(codigo, cambio);
EndAlgorithm
